from pysat.solvers import Glucose3

# Langford sequence L(2,9): length 18, values 1-9, each appearing twice
# Constraint: two copies of value v are exactly v+1 positions apart
# i.e., if v is at position i, the other copy is at position i+v+1

# Variables: x[i][v] = 1 if position i (0-indexed) contains value v
# Positions: 0..17, Values: 1..9

n = 9
length = 2 * n  # 18

# We'll use a direct backtracking search
def solve_langford(n):
    length = 2 * n
    seq = [0] * length
    used = [False] * (n + 1)  # used[v] = True if v has been placed

    def backtrack(pos):
        if pos == length:
            return all(used[v] for v in range(1, n+1))

        if seq[pos] != 0:
            return backtrack(pos + 1)

        for v in range(1, n + 1):
            if not used[v]:
                # Place v at pos and pos+v+1
                j = pos + v + 1
                if j < length and seq[j] == 0:
                    seq[pos] = v
                    seq[j] = v
                    used[v] = True
                    if backtrack(pos + 1):
                        return True
                    seq[pos] = 0
                    seq[j] = 0
                    used[v] = False

        return False

    if backtrack(0):
        return seq
    return None

result = solve_langford(9)
print("Result:", result)
if result:
    # Verify
    print("Length:", len(result))
    for v in range(1, 10):
        positions = [i for i, x in enumerate(result) if x == v]
        print(f"Value {v}: positions {positions}, gap = {positions[1] - positions[0]} (expected {v+1})")

# Let me try a more efficient approach - place values from largest to smallest
def solve_langford_v2(n):
    length = 2 * n
    seq = [0] * length

    def backtrack(v):
        if v == 0:
            return True

        # Try placing value v at each valid position
        for i in range(length - v - 1):
            j = i + v + 1
            if seq[i] == 0 and seq[j] == 0:
                seq[i] = v
                seq[j] = v
                if backtrack(v - 1):
                    return True
                seq[i] = 0
                seq[j] = 0

        return False

    if backtrack(n):
        return seq
    return None

